const dir = (await $`pwd`.text()).trim();
const listing = (await $`find . -maxdepth 1 -type f -name '*.txt' -print`.nothrow().text()).split('\n').filter(Boolean).sort();
const rows = [];
for (const p of listing) {
  const text = await file(p).text();
  const lines = text === '' ? 0 : text.split('\n').length - (text.endsWith('\n') ? 1 : 0);
  rows.push({ name: p.replace(/^\.\//, ''), lines, trailingNewline: text.endsWith('\n'), bytes: Buffer.byteLength(text) });
}
const table = rows.length
  ? rows.map(r => `${String(r.lines).padStart(6)}  ${r.name}${r.trailingNewline ? '' : '  (no final newline)'}`).join('\n')
  : '(no .txt files)';
({ dir, count: rows.length, total: rows.reduce((a, r) => a + r.lines, 0), table })

